// The story of Lilith in the Alphabet of Ben Sira, in the original Hebrew, shown untranslated on the Lilith page.
// Three passages copied verbatim from Otzar Midrashim (New York, 1915; public domain), "The Alphabet of ben Sira
// (alternative version)", section 34, as published by Sefaria. The page joins them with an ellipsis where text is left out.
// Kept: her creation from the same earth, her claim that the two are equal, the Name and her flight, the three angels,
// and her refusal to return. Left out: the crude detail of the quarrel, and the condition about her children.
// Do not edit the passages by hand: each is reproduced exactly as printed.
export const BEN_SIRA_LILITH: readonly string[] = [
  "כשברא הקב״ה אדם הראשון יחיד, אמר לא טוב היות האדם לבדו, ברא לו אשה מן האדמה כמוהו וקראה לילית, מיד התחילו מתגרין זה בזה",
  "אמרה לו שנינו שוין לפי ששנינו מאדמה, ולא היו שומעין זה לזה, כיון שראתה לילית אמרה שם המפורש ופרחה באויר העולם, עמד אדם בתפלה לפני קונו ואמר, רבש״ע אשה שנתת לי ברחה ממני, מיד שגר הקב״ה שלשה מלאכים הללו אחריה להחזירה",
  "עזבו אותה והלכו אחריה והשיגוה בתוך הים במים עזים שעתידין המצריים לטבוע בו וספרוה דבר ה' ולא רצתה לחזור"
]

export const BEN_SIRA_SOURCE_URL =
  'https://www.sefaria.org/Otzar_Midrashim%2C_The_Aleph_Bet_of_ben_Sira%2C_The_Alphabet_of_ben_Sira%2C_(alternative_version).34'
